var getAllProperties = async (query) => {
  const limit = query.limit ? Number(query.limit) : 10;
  const page = query.page ? Number(query.page) : 1;
  const skip = (page - 1) * limit;
  const sortBy = query.sortBy ? query.sortBy : "createdAt";
  const sortOrder = query.sortOrder ? query.sortOrder : "desc";
  const andConditions = [];
  if (query.searchTerm) {
    andConditions.push({
      OR: [
        {
          title: {
            contains: query.searchTerm,
            mode: "insensitive"
          }
        },
        {
          description: {
            contains: query.searchTerm,
            mode: "insensitive"
          }
        },
        {
          city: {
            contains: query.searchTerm,
            mode: "insensitive"
          }
        },
        {
          address: {
            contains: query.searchTerm,
            mode: "insensitive"
          }
        }
      ]
    });
  }
  if (query.location) {
    andConditions.push({
      OR: [
        {
          city: {
            contains: query.location,
            mode: "insensitive"
          }
        },
        {
          address: {
            contains: query.location,
            mode: "insensitive"
          }
        }
      ]
    });
  }
  if (query.minPrice || query.maxPrice) {
    andConditions.push({
      rentPrice: {
        ...query.minPrice && {
          gte: Number(query.minPrice)
        },
        ...query.maxPrice && {
          lte: Number(query.maxPrice)
        }
      }
    });
  }
  if (query.type) {
    andConditions.push({
      propertyType: {
        equals: query.type,
        mode: "insensitive"
      }
    });
  }
  if (query.categoryId) {
    andConditions.push({
      categoryId: query.categoryId
    });
  }
  if (query.status) {
    andConditions.push({
      status: query.status
    });
  }
  if (!query.status) {
    andConditions.push({
      status: "AVAILABLE"
    });
  }
  const properties = await prisma.property.findMany({
    where: {
      AND: andConditions
    },
    take: limit,
    skip,
    orderBy: {
      [sortBy]: sortOrder
    },
    include: {
      category: true,
      landlord: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true
        }
      }
    }
  });
  return properties;
};
