var updateRentalRequest = async (requestId, landlordId, payload) => {
  const result = await prisma.$transaction(async (tx) => {
    const rentalRequest = await tx.rentalRequest.findFirstOrThrow({
      where: {
        id: requestId,
        property: {
          landlordId
        }
      }
    });
    const currentStatus = rentalRequest.status;
    const nextStatus = payload.status;
    if (currentStatus === nextStatus) {
      throw new Error(
        `Rental request is already ${nextStatus}`
      );
    }
    switch (currentStatus) {
      case RentalRequestStatus.PENDING:
        if (![
          RentalRequestStatus.APPROVED,
          RentalRequestStatus.REJECTED
        ].includes(nextStatus)) {
          throw new Error(
            "Pending request can only be APPROVED or REJECTED"
          );
        }
        break;
      case RentalRequestStatus.APPROVED:
        if (nextStatus !== RentalRequestStatus.ACTIVE) {
          throw new Error(
            "Approved request can only become ACTIVE"
          );
        }
        break;
      case RentalRequestStatus.ACTIVE:
        if (nextStatus !== RentalRequestStatus.COMPLETED) {
          throw new Error(
            "Active request can only become COMPLETED"
          );
        }
        break;
      case RentalRequestStatus.REJECTED:
        throw new Error(
          "Rejected request cannot be updated"
        );
      case RentalRequestStatus.COMPLETED:
        throw new Error(
          "Completed request cannot be updated"
        );
    }
    const updatedRequest = await tx.rentalRequest.update({
      where: {
        id: requestId
      },
      data: {
        status: nextStatus,
        approvedAt: nextStatus === RentalRequestStatus.APPROVED ? /* @__PURE__ */ new Date() : rentalRequest.approvedAt
      },
      include: {
        property: {
          select: {
            id: true,
            title: true,
            address: true,
            city: true,
            rentPrice: true
          }
        },
        tenant: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true
          }
        }
      }
    });
    if (nextStatus === RentalRequestStatus.APPROVED) {
      await tx.property.update({
        where: {
          id: rentalRequest.propertyId
        },
        data: {
          status: PropertyStatus.RENTED
        }
      });
    }
    return updatedRequest;
  });
  return result;
};
